 left=ROOT/'tiles/r09_c11.candidate.png';right=ROOT/'tiles/r09_c12.candidate-v03.png';srcL=Image.open(left).convert('RGB');srcR=Image.open(right).convert('RGB');im=Image.new('RGB',(1254,1254));parts=[]
